mapper.select:

where 1 = 1

	and user_id = #{userId}


	and markorder = #{mark}


	and income = #{money}


	and pay = #{pay}

select
user_id,
type,
income,
pay,
total_before,
total,
create_time
from log_money${dbNodes}
where user_id =  #{userId}

	and type = #{req.enumMoney.type}


	and create_time >=  #{beginDay} and create_time <=  #{endDay}

order by create_time desc
